import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
old=json.loads((ROOT/'tasks'/'023_midnight_unread_modern_manhua_h3_12.json').read_text(encoding='utf-8'))
manifest=json.loads((ROOT/'tasks'/'023_midnight_unread_manifest.json').read_text(encoding='utf-8'))
SHOTS=json.loads("[[\"Wide shot of a midnight office\",\"LIN WAN sits alone at a desk while rain streaks the floor-to-ceiling windows. Her phone is dark beside her hand.\",\"The phone screen suddenly lights up with an unread-message icon; she raises her chin toward the empty office, her eyes narrowing.\",\"the camera pushes in with small amplitude at slow speed from wide to medium framing.\",\"Rain taps on the glass. A restrained phone vibration is followed by a faint chair creak.\"],[\"Over-the-shoulder close-up\",\"LIN WAN holds her phone at chest height, its screen showing a small photograph of herself beside GU YAN at a subway platform three years earlier; no readable text.\",\"She taps to enlarge the picture and freezes; her thumb stops moving as her eyes widen in shock.\",\"the camera pushes in with small amplitude at slow speed, keeping the phone and her face legible.\",\"A single soft touchscreen tap, a quiet breath, and rain against the distant windows.\"],[\"Medium side shot near the desks\",\"LIN WAN sits in the dim office facing the glass corridor door; distant footsteps approach from out of frame.\",\"She slowly stands and walks toward the door. A row of ceiling lights goes dark behind her, one after another, while she remains illuminated.\",\"the camera trucks right with small amplitude at slow speed alongside her.\",\"Measured distant footsteps, subtle shoe contact on the floor, and a faint electrical click as the lights go out.\"],[\"Medium-wide composition through the glass door\",\"LIN WAN stands inside the office; GU YAN stands beyond the glass with his back toward her, in a charcoal trench coat under cool corridor lighting.\",\"LIN WAN stops and cautiously lifts her right palm until her fingertips rest against the door glass. GU YAN remains still.\",\"the camera pushes in with small amplitude at slow speed while preserving both figures in frame.\",\"The rain hum continues softly, followed by a light fingertip tap against glass and shallow breathing.\"],[\"Close two-shot framed through glass\",\"GU YAN is seen from behind outside the office door, with LIN WAN visible on its other side.\",\"He turns his head and shoulders slowly toward her, revealing his tired face. They meet each other's gaze and hold still for the final beat.\",\"the camera holds a static shot so the head turn and eye contact remain readable.\",\"A quiet coat rustle, distant ventilation hum, and a barely audible inhale.\"],[\"Medium two-shot in a glass doorway\",\"LIN WAN stands just inside the glass office door; GU YAN waits in the dim corridor a few feet away.\",\"She pushes the glass door open and takes one small step toward him. He retreats half a step and drops his gaze before she can approach further.\",\"the camera holds a static shot, preserving the clear physical distance between them.\",\"Glass hinge movement, two quiet footsteps and the soft shift of GU YAN's coat.\"],[\"Close-up of hands and photograph\",\"GU YAN and LIN WAN face each other in the corridor; a folded, aged paper photograph protrudes from GU YAN's coat pocket.\",\"He draws out the photograph and places it into LIN WAN's open palm. She closes her fingers around one edge and gently smooths a crease with her thumb.\",\"the camera pushes in with small amplitude at slow speed to center the handoff and the folded paper.\",\"Dry paper unfolds, fabric brushes the sleeve, and restrained breathing continues.\"],[\"Warm medium two-shot on a subway platform, flashback three years earlier\",\"The same LIN WAN wears a cream cardigan, and the same GU YAN wears a white shirt. The station platform glows with warm afternoon light; GU YAN holds a transparent umbrella.\",\"He tilts the umbrella canopy to shelter LIN WAN from droplets near the platform entrance. She turns to him and gives a small, genuine smile.\",\"the camera arcs around them with small amplitude at slow speed, keeping the umbrella and both faces visible.\",\"Soft station ambience, drops falling on the umbrella canopy, and a delicate shift of fabric.\"],[\"Cool corridor close two-shot\",\"Back in the midnight office corridor, LIN WAN looks at the worn paper photograph while GU YAN stands a step away.\",\"Her eyes slowly redden but she does not cry. GU YAN tightens his right hand into a fist, then deliberately releases it, averting his gaze.\",\"the camera holds a static close two-shot with a gentle focus shift from her face to his hand.\",\"Distant rain, a slow exhale and faint clothing movement; no speech.\"],[\"Medium-wide corridor shot toward an elevator\",\"GU YAN stands closer to the elevator; LIN WAN remains behind him holding the folded photograph.\",\"The elevator doors slide open and cold white light spills across the floor. GU YAN turns and walks toward the opening while LIN WAN stretches out a hand toward his back.\",\"the camera tracks sideways with small amplitude at slow speed to retain both characters and the elevator.\",\"Elevator motor whirr, a soft opening chime and brisk footsteps on polished flooring.\"],[\"Medium close-up beside the elevator doorway\",\"The elevator doors begin sliding inward as GU YAN steps toward the cabin; LIN WAN is close behind him.\",\"LIN WAN quickly reaches forward and catches the fabric of GU YAN's sleeve before the doors meet. The sleeve pulls taut and GU YAN stops, turning slightly back toward her.\",\"the camera pushes in with small amplitude at slow speed to emphasize the visible grip.\",\"The elevator mechanism hums, fast footsteps stop abruptly, and fabric stretches with a short rustle.\"],[\"Close two-shot near the open elevator\",\"GU YAN faces LIN WAN and holds a second black phone; LIN WAN's hand is open below it.\",\"He places the phone into her palm. Its screen illuminates with a portrait of an unfamiliar woman, without readable text. LIN WAN looks up in shock; GU YAN remains grave and motionless.\",\"the camera pushes in with large amplitude at fast speed for the final second, ending on LIN WAN's widened eyes.\",\"A quiet phone vibration and sudden intake of breath; corridor ambience continues underneath.\"]]")
assert len(SHOTS)==len(old['steps'][0]['foreach'])==12
style=('Contemporary Chinese 2D manhua animation with crisp hand-drawn linework, controlled cel shading and softly painted backgrounds. '
       '16:9 wide frame. Consistent character design: LIN WAN, a 26-year-old woman with straight shoulder-length black hair parted to one side, dark almond eyes, beige blouse, fitted navy office blazer and charcoal pleated skirt. '
       'GU YAN, a tall lean 28-year-old man with neatly parted short black hair, narrow dark eyes, long charcoal trench coat and black turtleneck. '
       'A realistic but illustrated urban drama look, natural human proportions, expressive eyes and restrained acting. '
       'The present-day office has cool blue-gray storm lighting; flashback subway is warm and softly lit. '
       'Exactly the on-screen characters described for this shot; no extra people, subtitles, watermarks or scene cuts. ')
newjobs=[]
for idx, (oldjob,scene) in enumerate(zip(old['steps'][0]['foreach'],SHOTS),1):
    opening,initial,development,camera,sound=scene
    scene_style=style
    if idx==8:
        scene_style=scene_style.replace('beige blouse, fitted navy office blazer and charcoal pleated skirt','cream cardigan').replace('long charcoal trench coat and black turtleneck','white collared shirt')
    body=(f'integrated_multimodal_description: [Shot 1] {scene_style} '
        f'At 0.00-1.00 seconds: {opening}. {initial} '
        f'From 1.00-3.50 seconds: {development} '
        f'From 3.50-5.00 seconds: the final facial expression, object state and character positions settle and remain continuous. '
        f'During the action, {camera} Keep motion anatomically plausible, hands and props coherent, and the same faces across the shot.')
    prompt=body+'\n\noverall_soundscape: '+sound+'\n\nnon_diegetic_music: N/A'
    newjobs.append({'name':oldjob['name'],'set':{'140:131.prompt':prompt,'140:133.value':5,
                   '92.filename_prefix':f'video/024_midnight_unread_h3skill_S{idx:02d}'}})
    manifest['shots'][idx-1]['h3_skill_prompt']=prompt
task={'name':'024_midnight_unread_h3skill_12','steps':[{'id':'video','endpoint':'pika',
    'workflow':old['steps'][0]['workflow'],'foreach':newjobs}]}
assert old['steps'][0]['endpoint']=='pika'
out=ROOT/'tasks'/'024_midnight_unread_h3skill_12.json'
meta=ROOT/'tasks'/'024_midnight_unread_h3skill_manifest.json'
assert not out.exists() and not meta.exists()
out.write_text(json.dumps(task,ensure_ascii=False,indent=2),encoding='utf-8')
meta.write_text(json.dumps({'name':manifest['name'],'source_task':old['name'],
   'skill':'skill://shared/minimax-h3/h3-prompt-writing/SKILL.md',
   'guide':'skill://shared/minimax-h3/h3-prompt-writing/references/base-en.txt',
   'format':'T2VA; integrated_multimodal_description / overall_soundscape / non_diegetic_music',
   'shots':manifest['shots']},ensure_ascii=False,indent=2),encoding='utf-8')
print('CREATED',out.name,len(newjobs),'PROMPT_LENGTHS',[len(j['set']['140:131.prompt']) for j in newjobs])
